create schema if not exists aas;
set search_path to aas, public;

-- aa_trees condenses data/AAs/trees/{id}.json (157 files) into two tables;
-- tree_type and max_points are PRECOMPUTED at build time
-- (scripts/build_aas_db.py). node_id / spellcrc / first_parent_id are
-- census-assigned and exceed int4 (max observed ~4.29e9) — bigint.
-- aa_limits.unlocked_trees / visible_rows stay text (JSON strings the
-- Python json.loads).

CREATE TABLE _meta (
    key   text PRIMARY KEY,
    value text
);

CREATE TABLE aa_trees (
    id                       bigint  PRIMARY KEY,          -- census tree id (JSON filename stem)
    name                     text    NOT NULL,             -- e.g. "Cleric"
    tree_type                text    NOT NULL,             -- class | subclass | shadows | heroic | ...
    max_points               integer NOT NULL DEFAULT 0,   -- Σ maxtier × points_per_tier over its nodes
    is_warder_tree           integer NOT NULL DEFAULT 0,
    maximum_points           integer NOT NULL DEFAULT 0,
    minimum_points_required  integer NOT NULL DEFAULT 0,
    ofx_classification       text,
    ofy_classification       text,
    version                  integer
);

CREATE TABLE aa_nodes (
    tree_id                         bigint  NOT NULL REFERENCES aa_trees(id) ON DELETE CASCADE,
    node_id                         bigint  NOT NULL,
    name                            text    NOT NULL DEFAULT '',
    description                     text    NOT NULL DEFAULT '',
    classification                  text    NOT NULL DEFAULT '',
    node_group                      text    NOT NULL DEFAULT '',
    title                           text    NOT NULL DEFAULT '',
    title_level                     integer NOT NULL DEFAULT 0,
    xcoord                          integer NOT NULL,
    ycoord                          integer NOT NULL,
    icon_id                         bigint  NOT NULL DEFAULT 0,
    icon_backdrop                   bigint  NOT NULL DEFAULT -1,
    maxtier                         integer NOT NULL DEFAULT 1,
    points_per_tier                 integer NOT NULL DEFAULT 1,
    min_level                       integer NOT NULL DEFAULT 1,
    spellcrc                        bigint  NOT NULL DEFAULT 0,
    points_to_unlock                integer NOT NULL DEFAULT 0,
    points_global_to_unlock         integer NOT NULL DEFAULT 0,
    classification_points_required  integer NOT NULL DEFAULT 0,
    first_parent_id                 bigint,
    first_parent_required_tier      integer,
    PRIMARY KEY (tree_id, node_id)
);

CREATE INDEX idx_aa_nodes_tree ON aa_nodes (tree_id);

-- Per-expansion AA caps + era tree/row curation (from committed
-- data/AAs/aa_limits.json via scripts/build_aas_db.py).
CREATE TABLE aa_limits (
    xpac           text    PRIMARY KEY,             -- canonical expansion name
    aa_cap         integer NOT NULL DEFAULT 0,      -- adventure AA cap
    unlocked_trees text    NOT NULL DEFAULT '[]',   -- JSON array (text on purpose)
    -- JSON {tree_type: [ycoord, ...]} — rows visible in this era. A tree type
    -- absent from the map shows ALL rows (only partial trees are listed).
    visible_rows   text    NOT NULL DEFAULT '{}',
    notes          text
);

-- seeds
-- FULL DATA SEEDS, machine-generated from an aas catalogue build — never
-- hand-edit. They make every environment (prod, CI,
-- scratch leases, fresh dev) data-complete from migrations alone; future AA
-- updates flow through scripts/build_aas_db.py upserts against the DB.
-- 157 trees
ON CONFLICT (id) DO NOTHING;

-- 3695 nodes
ON CONFLICT (tree_id, node_id) DO NOTHING;
ON CONFLICT (tree_id, node_id) DO NOTHING;
ON CONFLICT (tree_id, node_id) DO NOTHING;
ON CONFLICT (tree_id, node_id) DO NOTHING;
ON CONFLICT (tree_id, node_id) DO NOTHING;
ON CONFLICT (tree_id, node_id) DO NOTHING;
ON CONFLICT (tree_id, node_id) DO NOTHING;
ON CONFLICT (tree_id, node_id) DO NOTHING;

-- 12 limits
ON CONFLICT (xpac) DO NOTHING;

-- 5 _meta provenance stamps (from the seeding build)
ON CONFLICT (key) DO NOTHING;
