    (70, 3210521397, 'Sanguine Sacrifice', 'The sorcerer uses their own blood to amplify the damage of their magic, restoring the power used to cast the spell instantly at the cost of their health. Sanguine Sacrifice has a recurring health cost of 1% every second.', 'Heroic', 'heroic_endline', '', 0, 34, 16, 748, 461, 1, 2, 1, 3048601538, 0, 0, 48, NULL, NULL),
    (70, 3361446819, 'Mystical Field', 'Mystical Field surrounds the sorcerer in arcane magicks, preventing them from being hit with Area of Effect abilities and being interrupted and allowing them to cast while moving for a short duration. Any enemy entering the field around the sorcerer will take magic damage. This spell drains power at a prodigious rate and can be toggled off early.  If the caster enters PVP combat, the duration of this effect will be reduced.', 'Heroic', 'heroic_endline', '', 0, 22, 16, 583, 461, 1, 2, 1, 3266496340, 0, 0, 48, NULL, NULL),
    (70, 3378241010, 'Mystical Overflow', 'Inflicts additional magic damage on targets within a small radius of the target when a damage spell is cast. Mystical Overflow can hit targets that are not currently engaged and should be toggled off in situations where that effect is undesirable.', 'Heroic', '', '', 0, 41, 11, 296, 461, 10, 1, 1, 2246766162, 0, 0, 20, NULL, NULL),
