    (100, 1269703992, 'Spiritual Stability', 'Immunization allows the target to cast while moving and makes them immune to knockbacks.', 'Spirit Guide', '', 'the Spirit Guide', 1, 8, 17, 270, 460, 1, 1, 1, 1472643429, 0, 0, 6, NULL, NULL),
    (100, 1381367836, 'Enhanced Concentration', 'The mystic has a chance to be able to cast while moving when they cast their primary wards.', 'Prestige', '', '', 0, 14, 1, 17, 461, 3, 1, 1, 755314119, 0, 0, 0, NULL, NULL),
    (100, 1435112800, 'Snow Rhino''s Power', 'Increases the weapon damage bonus of the group when the mystic enters Ferocity of Spirits with two spell increments. Cannot trigger more than once every 30 seconds.', 'Spirit Beast', '', '', 0, 35, 14, 470, 461, 3, 1, 1, 3311836273, 0, 0, 0, 3114239000, 3),
    (100, 1672491516, 'Spirits of Midnight', '', 'Prestige', '', '', 0, 41, 4, 343, 461, 2, 1, 1, 1926130061, 0, 0, 0, NULL, NULL),
    (100, 2067395976, 'Helpful Spirits', 'Ancestral Support will heal the target when it triggers.', 'Spirit Guide', '', '', 0, 14, 14, 211, 458, 3, 1, 1, 682456455, 0, 0, 0, 546756002, 3),
    (100, 2411094965, 'Mystic Ritual', 'Ritual of Alacrity will gain triggered effects that ward when casting heals and inflict damage when attacking.', 'Prestige Mastery', '', '', 0, 22, 11, 619, 460, 3, 1, 1, 526052004, 10, 0, 0, NULL, NULL),
    (100, 2459813165, 'Invigorate', 'The priest''s heals have a chance to increase the target''s flurry chance and doublecast chance.', 'Prestige', '', '', 0, 2, 1, 733, 460, 3, 1, 1, 2212732252, 0, 0, 0, NULL, NULL),
    (100, 2625755279, 'Whispers of the Past', 'Ancestral Support will make the group immune to certain control effects.', 'Spirit Guide', '', '', 0, 8, 14, 225, 458, 3, 1, 1, 3474282624, 0, 0, 0, 546756002, 3),
    (100, 2786529138, 'Full Moon', 'Enhances Bolster to improve movement speed and Crit Bonus. Additionally, Bolster shapeshifts the target into a werewolf and grants a lifetap on attacks.', 'Prestige', '', '', 0, 29, 4, 375, 460, 1, 1, 1, 3077134083, 0, 0, 0, NULL, NULL),
    (100, 2989635687, 'White Wolf''s Howl', '', 'Spirit Beast', '', '', 0, 41, 14, 188, 461, 3, 1, 1, 585019766, 0, 0, 0, 3114239000, 3),
    (100, 3114239000, 'Ferocity of Spirits', 'Grants the mystic a chance to gain an incremental Crit Bonus augmentation. This ability increments to 3 and does not refresh the duration once at rank 3.', 'Prestige Mastery', '', '', 0, 35, 11, 585, 461, 3, 1, 1, 2660023274, 10, 0, 0, NULL, NULL),
    (100, 3318168136, 'Multi-Attack Mastery', 'Grant''s Crit Bonus Overcap to the Mystic.', 'Prestige Expertise', '', '', 0, 35, 7, 224, 461, 1, 1, 1, 3568919097, 0, 0, 0, NULL, NULL),
    (100, 3385278986, 'Potent Medium', 'Grant''s Fervor to the Mystic.', 'Prestige Expertise', '', '', 0, 8, 7, 206, 461, 1, 1, 1, 3063181265, 0, 0, 0, NULL, NULL),
    (100, 3424756157, 'Spiritual Medium', 'Makes Ancestral Avatar apply to the group.', 'Prestige Mastery', '', '', 0, 22, 17, 387, 458, 1, 2, 1, 3366231788, 20, 0, 0, NULL, NULL),
    (100, 3951487001, 'Past''s Vengeance', 'Ancestral Support will gain a chance to inflict magic damage to enemies.', 'Spirit Guide', '', '', 0, 2, 14, 267, 458, 3, 1, 1, 3088214038, 0, 0, 0, 546756002, 3),
    (100, 4098263755, 'Barrier of the Spirits', 'Wards the target based on the number of increments of Ferocity of Spirits. This spell can be cast while casting other spells.', 'Spirit Beast', '', 'the Spirit Beast', 1, 35, 17, 502, 460, 1, 1, 1, 3783315302, 0, 0, 6, NULL, NULL),
    (100, 4220322430, 'Brainstorm', 'The priest''s hostile actions have a chance to trigger damage reduction for their group.', 'Prestige', '', '', 0, 41, 1, 50, 458, 3, 1, 1, 2229153701, 0, 0, 0, NULL, NULL),
    (101, 526270662, 'Dream Haunter', 'Passively grants the defiler a chance for hostile spells to finish the reuse of Nightmares or Maelstrom.', 'Prestige', '', '', 0, 41, 4, 80, 461, 2, 1, 1, 1288356041, 0, 0, 0, NULL, NULL),
    (101, 754986201, 'Death Cries', 'A replacement spell for Deathward. This spell casts quicker and becomes far more powerful than Deathward when the target is below 50% health.', 'Prestige', '', '', 0, 14, 4, 100, 460, 1, 1, 1, 169022251, 0, 0, 0, NULL, NULL),
    (101, 805641313, 'Defiled Alacrity', 'Carrion Warding and Purulence have a chance to finish the reuse of Ancestral Channeling.', 'Prestige', '', '', 0, 2, 4, 71, 461, 2, 1, 1, 387326867, 0, 0, 0, NULL, NULL),
    (101, 823158031, 'Wraith Howl', 'Increases the health threshold of Wraithwall.', 'Wraithcaller', '', '', 0, 8, 14, 688, 460, 3, 1, 1, 1529915764, 0, 0, 0, 3601011656, 3),
    (101, 1175934361, 'Dominated Defenses', 'When Wraithwall absorbs damage, it will reduce incoming damage to the target for a short duration.', 'Wraithcaller', '', '', 0, 2, 14, 540, 460, 3, 1, 1, 741841378, 0, 0, 0, 3601011656, 3),
    (101, 1298558817, 'Spiritrealm', 'Improves the range and radius of the defiler''s beneficial and impairment spells.', 'Prestige', '', '', 0, 29, 1, 263, 461, 3, 1, 1, 519237486, 0, 0, 0, NULL, NULL),
    (101, 1336558194, 'Empowered Dominion', 'When the defiler casts spells that are not Deathward, Death Cries or Ancient Shroud, they grant the group additional Crit Bonus that dispels when they do cast Deathward, Death Cries or Ancient Shroud. This increments up to 12 times. Carrion Warding, Spiritual Sacrifice and Wraithwall do not modify the increment count or remove the effect.', 'Prestige Mastery', '', '', 0, 35, 11, 413, 458, 3, 1, 1, 3745958755, 10, 0, 0, NULL, NULL),
    (101, 1596402426, 'Spiritarmor', 'Spiritual Dominion grants increased mitigation to the group. The effect is multiplied by the amount of increments of Spiritual Dominion.', 'Soul Dominator', '', '', 0, 41, 14, 297, 458, 3, 1, 1, 2560270978, 0, 0, 0, 1336558194, 3),
    (101, 1623756242, 'Empowered Barrier', 'When the defiler casts four or more spells that are not Deathward, Death Cries or Ancient Shroud, they gain an additional ward on the target when they do cast Deathward, Death Cries or Ancient Shroud. Once one of these spells is cast, the count resets. Carrion Warding, Spiritual Sacrifice and Wraithwall do not modify the count or apply the ward.', 'Prestige', '', '', 0, 14, 1, 0, 460, 3, 1, 1, 1205580320, 0, 0, 0, NULL, NULL),
    (101, 1654878504, 'Phantasmal Barrier', 'Applies a small ward to the defiler''s two allies with the lowest health percentages. The targets must be within 50 meters of the defiler. This spell can be cast while casting other spells.', 'Prestige Mastery', '', '', 0, 22, 11, 671, 460, 3, 1, 1, 2770270544, 10, 0, 0, NULL, NULL),
    (101, 1763030455, 'Spiritual Sacrifice', 'This spell is applied to the target ally and cannot be cast on the defiler. It reduces the defilers max health and grants the target a health increase. If the target ally dies while this spell is active, their group will receive damage reduction for a short duration. This spell has no reuse if it is toggled off manually. This spell can be cast while casting other spells.', 'Wraithcaller', '', 'the Wraithcaller', 1, 8, 17, 187, 458, 1, 1, 1, 3244797095, 0, 0, 6, NULL, NULL),
    (101, 1973917451, 'Ward''s Bane', 'Inflicts damage to the target and nearby enemies when they strike the caster''s primary wards.', 'Prestige Mastery', '', '', 0, 22, 17, 670, 461, 1, 2, 1, 1617023654, 20, 0, 0, NULL, NULL),
    (101, 2305011690, 'Spiritwrath', 'A replacement for Putrefy. This spell inflicts poison damage and reduces the target''s attributes. The damage over time, STR, AGI and INT components are multiplied by the amount of increments of this spell the caster has active on the target.', 'Soul Dominator', '', 'the Soul Dominator', 1, 35, 17, 313, 459, 1, 1, 1, 2491207063, 0, 0, 6, NULL, NULL),
    (101, 2459813165, 'Invigorate', 'The priest''s heals have a chance to increase the target''s flurry chance and doublecast chance.', 'Prestige', '', '', 0, 2, 1, 733, 460, 3, 1, 1, 2212732252, 0, 0, 0, NULL, NULL),
    (101, 3097430013, 'Spirit Domination', 'As Spiritual Dominion increments, Ancient Shroud, Deathward and Death Cries will cast faster.', 'Soul Dominator', '', '', 0, 35, 14, 501, 458, 3, 1, 1, 2132971397, 0, 0, 0, 1336558194, 3),
    (101, 3106491250, 'Critical Channeling', 'Grant''s Crit Bonus Overcap to the Defiler.', 'Prestige Expertise', '', '', 0, 35, 7, 45, 461, 1, 1, 1, 3938306941, 0, 0, 0, NULL, NULL),
    (101, 3482859371, 'Ethereal Souls', 'Improves the Crit Bonus of Spiritual Dominion.', 'Soul Dominator', '', '', 0, 29, 14, 416, 458, 3, 1, 1, 136691475, 0, 0, 0, 1336558194, 3),
    (101, 3601011656, 'Wraithwall', 'Wards the target from all damage. Only absorbs damage that would cause the target to fall below 20% health. Higher ranks of this ability lower the reuse time.', 'Prestige Mastery', '', '', 0, 8, 11, 701, 460, 3, 1, 1, 1179622105, 10, 0, 0, NULL, NULL),
    (101, 3601352712, 'Soultemper', 'Wraithwall will apply an extremely fast regenerating ward to the target.', 'Wraithcaller', '', '', 0, 14, 14, 381, 460, 3, 1, 1, 3163063411, 0, 0, 0, 3601011656, 3),
    (101, 3673783880, 'Countenance of Defiled Spirits', 'A replacement for Sinister Countenance. The defiler takes on a wraith form and increases their wisdom along with the group''s stamina, spell resistance and the ability to see invisible creatures. The defiler gains increased movement speed as well.', 'Prestige', '', '', 0, 29, 4, 381, 458, 1, 1, 1, 2305687111, 0, 0, 0, NULL, NULL),
    (101, 4216967108, 'Potent Medium', 'Grant''s Fervor to the Defiler.', 'Prestige Expertise', '', '', 0, 8, 7, 185, 461, 1, 1, 1, 3695898678, 0, 0, 0, NULL, NULL),
    (101, 4220322430, 'Brainstorm', 'The priest''s hostile actions have a chance to trigger damage reduction for their group.', 'Prestige', '', '', 0, 41, 1, 50, 458, 3, 1, 1, 2229153701, 0, 0, 0, NULL, NULL),
    (102, 348721694, 'Champion''s Interception', 'Grants Champion''s Watch and Champion''s Interception. Champion''s Watch is a group spell that increments Champion''s Sight whenever a non-fighter is hit by an enemy. Champion''s Sight increments to 50. Champion''s Interception consumes Champion''s Sight and applies damage reduction to non-fighters in the group based on the number of increments of Champion''s Sight consumed. This spell can be toggled off early to gain some Champion''s Sight increments back. Champion''s Interception can be used through most control effects. Higher ranks lower the base reuse time.', 'Prestige Mastery', '', '', 0, 8, 11, 678, 458, 3, 1, 1, 3547634278, 10, 0, 0, NULL, NULL),
    (102, 419075992, 'Blades of Protection', 'Adds additional strikes to Grit.', 'Charging Defender', '', '', 0, 35, 14, 527, 459, 3, 1, 1, 478128329, 0, 0, 0, 2378187684, 3),
    (102, 694503545, 'Will of the Champion', 'Reduces the base cast time of Champion''s Interception and increases its duration.', 'Champion', '', '', 0, 2, 14, 222, 458, 3, 1, 1, 2004618495, 0, 0, 0, 348721694, 3),
    (102, 1036723666, 'Retribution of the Protector', 'Guardian Sphere''s triggers have a chance to finish the cooldown of the guardian''s single target impairment attacks.', 'Prestige', '', '', 0, 41, 4, 125, 461, 2, 1, 1, 1475078569, 0, 0, 0, NULL, NULL),
    (102, 1242567872, 'Sphere of Defense', 'Reduces the base reuse of  Guardian Sphere.', 'Prestige Mastery', '', '', 0, 22, 17, 662, 458, 1, 2, 1, 1460631229, 20, 0, 0, NULL, NULL),
    (102, 1583511791, 'Champion''s Shout', 'Champion''s Interception will increase the guardian''s threat generation by a percentage of the damage they inflict. Also, Champion''s Watch will reduce incoming damage to the guardian.', 'Champion', '', '', 0, 8, 14, 654, 458, 3, 1, 1, 8076393, 0, 0, 0, 348721694, 3),
    (102, 1704728844, 'Champion''s Stand', 'Reduces damage to all priests in the guardian''s raid.', 'Champion', '', 'the Protecting Champion', 1, 8, 17, 364, 458, 1, 1, 1, 1261767663, 0, 0, 6, NULL, NULL),
    (102, 1741562348, 'Stalwart Aura', 'When healed, the fighter has a chance to reduce all incoming damage for a short duration. With higher ranks, the trigger chance and trigger reuse are improved.', 'Prestige', '', '', 0, 2, 1, 66, 461, 3, 1, 1, 1088232990, 0, 0, 0, NULL, NULL),
    (102, 1814717042, 'Stalwart Wall', 'Grant''s Fervor to the Guardian.', 'Prestige Expertise', '', '', 0, 8, 7, 290, 461, 1, 1, 1, 4240894819, 0, 0, 0, NULL, NULL),
    (102, 1878198901, 'Avenging Strikes', '', 'Prestige', '', '', 0, 29, 1, 670, 459, 3, 1, 1, 97764878, 0, 0, 0, NULL, NULL),
    (102, 1878894350, 'Defender''s Power', 'Increases the damage of Defender''s Charge. This applies before potency.', 'Charging Defender', '', '', 0, 29, 14, 259, 459, 3, 1, 1, 1803065439, 0, 0, 0, 2378187684, 3),
    (102, 2348840038, 'Field Commander', 'When using hostile actions, the fighter has a chance to grant the group additional damage when they attack. The duration of this effect improves with higher ranks.', 'Prestige', '', '', 0, 41, 1, 740, 458, 3, 1, 1, 3751081065, 0, 0, 0, NULL, NULL),
    (102, 2378187684, 'Defender''s Charge', 'Inflicts melee damage on the target. The damage is greatly increased if the guardian is not the enemy''s current target. Applies additional damage and damage reduction to the guardian when the guardian uses their next combat art. Higher ranks of this ability lower the base reuse time. The triggered effects can increment up to three times each.', 'Prestige Mastery', '', '', 0, 35, 11, 749, 459, 3, 1, 1, 1249758172, 10, 0, 0, NULL, NULL),
    (102, 2612801126, 'Blade Crusher', 'Grant''s Crit Bonus Overcap to the Guardian.', 'Prestige Expertise', '', '', 0, 35, 7, 130, 461, 1, 1, 1, 4053590557, 0, 0, 0, NULL, NULL),
    (102, 2809573847, 'Protector''s Will', '', 'Prestige', '', '', 0, 2, 4, 439, 461, 2, 1, 1, 932853958, 0, 0, 0, NULL, NULL),
    (102, 3118093800, 'Champion''s Glare', 'Provoke has a chance to provide increments of Champion''s Sight.', 'Champion', '', '', 0, 14, 14, 316, 458, 3, 1, 1, 3888320878, 0, 0, 0, 348721694, 3),
    (102, 3128131951, 'Unstoppable Wall', 'Avoiding attacks while Defensive Minded is active will grant the guardian the ability to absorb the next attack.', 'Prestige', '', '', 0, 14, 4, 660, 461, 1, 1, 1, 715065470, 0, 0, 0, NULL, NULL),
    (102, 3267813709, 'Stalwart Conviction', 'Passively increases the amount of health gained from stamina.', 'Prestige Mastery', '', '', 0, 22, 11, 196, 461, 3, 1, 1, 3326336540, 10, 0, 0, NULL, NULL),
    (102, 3587984450, 'Protecting Spirit', 'Whenever other players in the guardian''s raid take melee damage, the guardian will gain increased Crit Bonus.', 'Charging Defender', '', 'the Charging Defender', 1, 35, 17, 664, 458, 1, 1, 1, 3975239314, 0, 0, 6, NULL, NULL),
    (102, 4156235876, 'Protecting Stance', 'The guardian''s temporary mitigation augmentations reduce additional damage.', 'Prestige', '', '', 0, 14, 1, 690, 461, 3, 1, 1, 1733798261, 0, 0, 0, NULL, NULL),
    (102, 4167834460, 'Retribution Sphere', 'The guardian''s critical damage will be increased whenever Guardian Sphere triggers.', 'Prestige', '', '', 0, 29, 4, 501, 458, 1, 1, 1, 2454509351, 0, 0, 0, NULL, NULL),
    (102, 4282563231, 'Defensive Bulwark', 'Increases the size of the damage reduction effect on Grit.', 'Charging Defender', '', '', 0, 41, 14, 663, 459, 3, 1, 1, 4224157134, 0, 0, 0, 2378187684, 3),
    (103, 89776030, 'Final Rampage', 'Berserker Onslaught, Bloodbath and Utter Destruction have a chance to finish the cooldown of Rampage.', 'Prestige', '', '', 0, 41, 4, 334, 461, 2, 1, 1, 1530960664, 0, 0, 0, NULL, NULL),
    (103, 268560164, 'Saga of Bloodshed', 'Inflicts melee damage to enemies surrounding the berserker. For every target the spell hits, the berserker gets an increment of Saga, which inflicts additional damage with the next strike and grants Crit Bonus to the berserker''s group. Higher ranks of this ability reduce the reuse time. Saga can increment up to 6 times.', 'Prestige Mastery', '', '', 0, 35, 11, 682, 457, 3, 1, 1, 344250485, 10, 0, 0, NULL, NULL),
    (103, 360372452, 'Thrill of Combat', 'Improves the Crit Bonus that Saga grants to the group.', 'Sagas', '', '', 0, 41, 14, 569, 461, 3, 1, 1, 12361033, 0, 0, 0, 268560164, 3),
    (103, 638773968, 'Critical Rage', 'Grant''s Fervor to the Berserker.', 'Prestige Expertise', '', '', 0, 8, 7, 115, 461, 1, 1, 1, 3786367656, 0, 0, 0, NULL, NULL),
    (103, 687768374, 'Battleworn', 'Passively increases the amount of health gained from stamina.', 'Prestige Mastery', '', '', 0, 22, 11, 196, 461, 3, 1, 1, 1027131035, 10, 0, 0, NULL, NULL),
    (103, 1426003820, 'Rampaging Vengeance', 'Following Rampaging Resiliance''s application, the berserker gets increased weapon damage.', 'Rampager', '', '', 0, 14, 14, 419, 461, 3, 1, 1, 1217917745, 0, 0, 0, 2299049630, 3),
    (103, 1466036281, 'Rampager', 'The berserker''s area of effect abilities do additional damage.', 'Prestige', '', '', 0, 29, 1, 136, 457, 3, 1, 1, 158905535, 0, 0, 0, NULL, NULL),
    (103, 1741562348, 'Stalwart Aura', 'When healed, the fighter has a chance to reduce all incoming damage for a short duration. With higher ranks, the trigger chance and trigger reuse are improved.', 'Prestige', '', '', 0, 2, 1, 66, 461, 3, 1, 1, 1088232990, 0, 0, 0, NULL, NULL),
    (103, 2244330869, 'Saga of the Ages', 'Increases the damage of Saga of Bloodshed. This applies before potency.', 'Sagas', '', '', 0, 29, 14, 413, 457, 3, 1, 1, 2416148696, 0, 0, 0, 268560164, 3),
    (103, 2299049630, 'Rampager''s Resilience', 'Prevents the berserker from dying when they take fatal damage. The berserker or one of their allies must strike a death blow within the duration of the triggered effect or the berserker will be unable to attack for a short duration. Higher ranks of this ability lower the base reuse time.', 'Prestige Mastery', '', '', 0, 8, 11, 390, 461, 3, 1, 1, 2374863311, 10, 0, 0, NULL, NULL),
    (103, 2348840038, 'Field Commander', 'When using hostile actions, the fighter has a chance to grant the group additional damage when they attack. The duration of this effect improves with higher ranks.', 'Prestige', '', '', 0, 41, 1, 740, 458, 3, 1, 1, 3751081065, 0, 0, 0, NULL, NULL),
    (103, 2737755178, 'Power Stance', 'Grant''s Crit Bonus Overcap to the Berserker.', 'Prestige Expertise', '', '', 0, 35, 7, 473, 461, 1, 1, 1, 4248277164, 0, 0, 0, NULL, NULL),
    (103, 3007789675, 'Rampager''s Vitality', 'Increases the berserker''s health and riposte chance following Rampager''s Resilience triggering.', 'Rampager', '', '', 0, 8, 14, 260, -1, 3, 1, 1, 2939149878, 0, 0, 0, 2299049630, 3),
    (103, 3179522246, 'Ragebarrier', 'The berserker''s temporary mitigation augmentations reduce additional damage.', 'Prestige', '', '', 0, 14, 1, 328, 461, 3, 1, 1, 2050891966, 0, 0, 0, NULL, NULL),
    (103, 3237929232, 'Utter Destruction', 'A replacement for Demolish. A high damage attack that hits enemies surrounding the target and stifles them all for a short duration.', 'Prestige', '', '', 0, 29, 4, 495, 457, 1, 1, 1, 2665981334, 0, 0, 0, NULL, NULL),
    (103, 3292531453, 'Rage Face', 'Increases the amount of time the berserker has to strike the death blow. At rank three, the berserker will gain a short duration stoneskin after Rampager''s Resilience triggers.', 'Rampager', '', '', 0, 2, 14, 748, 461, 3, 1, 1, 3626561184, 0, 0, 0, 2299049630, 3),
    (103, 3324055637, 'Empowering Rage', 'Open Wounds will grant the group increased damage and remove the casting time of some of the berserker''s area effect abilities.', 'Sagas', '', 'the Living Saga', 1, 35, 17, 524, 461, 1, 1, 1, 3128628509, 0, 0, 6, NULL, NULL),
    (103, 3929906062, 'Unstoppable', 'The berserker instantly breaks out of certain control effects once per minute each. The berserker will be immune to those control effects for a short duration.', 'Prestige Mastery', '', '', 0, 22, 17, 635, 461, 1, 2, 1, 3541074270, 20, 0, 0, NULL, NULL),
    (103, 3981326709, 'Frenzied Berserker', '', 'Prestige', '', '', 0, 2, 4, 439, 461, 2, 1, 1, 720613645, 0, 0, 0, NULL, NULL),
    (103, 4031449549, 'Berserk Fury', 'The berserker will take less damage when Battle Frenzy is active.', 'Prestige', '', '', 0, 14, 4, 679, 461, 1, 1, 1, 938901941, 0, 0, 0, NULL, NULL),
    (103, 4072863203, 'Combat Saga', 'Adds additional slashing damage to Saga.', 'Sagas', '', '', 0, 35, 14, 440, 457, 3, 1, 1, 3875844174, 0, 0, 0, 268560164, 3),
    (103, 4099430420, 'Rampager''s Grit', 'When the berserker drops below 75%, 50% and 25% health thresholds, they get damage reduction for a short duration. This increments up to 3 times and each threshold can only trigger once every 15 seconds. Additional increments increase the amount of damage reduced and do not refresh the duration.', 'Rampager', '', 'the Rampager', 1, 8, 17, 669, 461, 1, 1, 1, 1924311002, 0, 0, 6, NULL, NULL),
    (104, 661476173, 'Divine Wall', 'Grant''s Fervor to the Paladin.', 'Prestige Expertise', '', '', 0, 8, 7, 74, 461, 1, 1, 1, 8285375, 0, 0, 0, NULL, NULL),
    (104, 764494954, 'Bringer of Justice', 'Grant''s Crit Bonus Overcap to the Paladin.', 'Prestige Expertise', '', '', 0, 35, 7, 701, 461, 1, 1, 1, 2114307173, 0, 0, 0, NULL, NULL),
    (104, 861608305, 'Divine Faith', 'Reduces the base cast speed and increases the duration of Faith.', 'Faith', '', '', 0, 14, 14, 670, 461, 3, 1, 1, 1501287690, 0, 0, 0, 4031538949, 3),
    (104, 1268730849, 'Zealous Defender', 'Passively increases the amount of health gained from stamina.', 'Prestige Mastery', '', '', 0, 22, 11, 196, 461, 3, 1, 1, 2351088537, 10, 0, 0, NULL, NULL),
    (104, 1312911696, 'Smite Infidel', 'Lay on Hands will apply a large triggered damage effect to the paladin.', 'Prestige', '', '', 0, 29, 4, 353, 461, 1, 1, 1, 500560223, 0, 0, 0, NULL, NULL),
    (104, 1717548882, 'Zealous Power', 'Removes the power cost of Consecrate and allows Consecrate to restore power to the paladin with each pulse.', 'Prestige Mastery', '', '', 0, 22, 17, 734, 461, 1, 2, 1, 1939469055, 20, 0, 0, NULL, NULL),
    (104, 1741562348, 'Stalwart Aura', 'When healed, the fighter has a chance to reduce all incoming damage for a short duration. With higher ranks, the trigger chance and trigger reuse are improved.', 'Prestige', '', '', 0, 2, 1, 66, 461, 3, 1, 1, 1088232990, 0, 0, 0, NULL, NULL)
INSERT INTO aa_nodes (tree_id, node_id, name, description, classification, node_group, title, title_level, xcoord, ycoord, icon_id, icon_backdrop, maxtier, points_per_tier, min_level, spellcrc, points_to_unlock, points_global_to_unlock, classification_points_required, first_parent_id, first_parent_required_tier) VALUES
    (104, 1766143679, 'Divine Territory', 'Passively allows the paladin to build charges of Divine Justice when using spells or combat arts. Divine Justice increments at 3 per attack target and maxes at 60. Divine Territory inflicts divine damage to enemies surrounding the paladin based on the number of charges of Divine Justice the paladin has active. For each target struck, the paladin gains an increment of True Territory which increases their attack speed and Multi-Attack Chance. True Territory increments up to 8 times.', 'Prestige Mastery', '', '', 0, 35, 11, 746, 457, 3, 1, 1, 4188651438, 10, 0, 0, NULL, NULL),
