INSERT INTO aa_limits (xpac, aa_cap, unlocked_trees, visible_rows, notes) VALUES
    ('Age of Discovery', 320, '["class", "subclass", "shadows", "heroic", "tradeskill", "tradeskill_general", "warder"]', '{}', 'General tradeskill AA tree added; Beastlord class introduced with Warder trees'),
    ('Altar of Malice', 350, '["class", "subclass", "shadows", "heroic", "tradeskill", "tradeskill_general", "warder", "prestige", "dragon"]', '{}', 'No new tree types'),
    ('Chains of Eternity', 320, '["class", "subclass", "shadows", "heroic", "tradeskill", "tradeskill_general", "warder", "prestige"]', '{}', 'Prestige trees added — two per class (conversion + expertise)'),
    ('Desert of Flames', 0, '[]', '{}', 'No AA system yet'),
    ('Destiny of Velious', 300, '["class", "subclass", "shadows", "heroic", "tradeskill"]', '{}', 'Heroic AA tree added — one per archetype'),
    ('Echoes of Faydwer', 100, '["class", "subclass", "tradeskill"]', '{"class": [0, 1, 2, 3, 4], "subclass": [0, 3, 6, 9, 13]}', 'Subclass (Expertise) trees added — one per class; tradeskill AA tree added (own 45-pt cap, separate from the adventure cap). Class rows 5-6 and subclass rows 16 (70-point row) + 19 (final) are the Sentinel''s Fate revamp — hidden. Verified empirically against live Wuoshi census data (300 chars, no spent points beyond these rows).'),
    ('Kingdom of Sky', 50, '["class"]', '{"class": [0, 1, 2, 3, 4]}', 'AA system introduced — one class tree per archetype. Class tree rows 5-6 (8-rank skills + second endline) are the Sentinel''s Fate revamp — hidden here.'),
    ('Rise of Kunark', 140, '["class", "subclass", "tradeskill"]', '{"class": [0, 1, 2, 3, 4], "subclass": [0, 3, 6, 9, 13]}', 'AA cap increased, no new tree types or tree content'),
    ('Sentinel''s Fate', 250, '["class", "subclass", "shadows", "tradeskill"]', '{}', 'AA cap increased; class trees gain rows 5-6 (8-rank skills + endline), subclass trees gain rows 16 (70-point gate) + 19 (final) — all rows visible from here on'),
    ('Shattered Lands', 0, '[]', '{}', 'No Alternate Advancement system exists'),
    ('Tears of Veeshan', 350, '["class", "subclass", "shadows", "heroic", "tradeskill", "tradeskill_general", "warder", "prestige", "dragon"]', '{}', 'Dragon AA trees added'),
    ('The Shadow Odyssey', 200, '["class", "subclass", "shadows", "tradeskill"]', '{"class": [0, 1, 2, 3, 4], "subclass": [0, 3, 6, 9, 13]}', 'Shadows tree added — one per class, cross-archetype nodes (whole tree from launch). Class/subclass trees still pre-revamp.')
